const choices={fromType:['rms','interval','average'],toType:['interval','rms','average'],domain:['TWT','depth'],normalisation:['none','peak'],direction:['twt-to-depth','depth-to-twt'],event:['peak','trough','zero-up','zero-down'],format:['obj','json'],model:['shuey2','shuey3'],method:['aki-richards','shuey2','shuey3'],task:['regression','classification'],target:['RESQML','GRDECL']};
const numericNulls=new Set(['dt','waveletDt','frequencyHz','durationSeconds','traceSpacing','datumAtAxisStart','referenceSample','nx','ny','nz','sampleCount','apertureMetres','maximumShiftSeconds']);
export function readEnginePayload(s){const value=JSON.parse(s.payload||'{}');if(!value||Array.isArray(value)||typeof value!=='object')throw new Error('Engine settings must be a JSON object.');return value;}
function currentOperation(tool,payload){const original=operations[tool];if(!original)return null;const value=original.key?.split('.').reduce((item,part)=>item?.[part],payload),items=[...original.items];if(value&&!items.some(item=>item[0]===value))items.push([value,'Saved operation: '+value,{}]);return {spec:{...original,items},entry:items.find(item=>item[0]===value)||items[0],value};}
export function selectOperation(s,value){
 const payload=readEnginePayload(s),operation=currentOperation(s.tool,payload);if(!operation)return;
 const entry=operation.spec.items.find(item=>item[0]===value)||operation.entry;
 for(const [key,defaultValue] of Object.entries(entry[2]))if(payload[key]===undefined&&defaultValue!==null)payload[key]=defaultValue;
 if(operation.spec.key){const path=operation.spec.key.split('.');let target=payload;for(const key of path.slice(0,-1)){if(target[key]===undefined)target[key]={};if(!target[key]||typeof target[key]!=='object'||Array.isArray(target[key]))throw new Error('Review the configuration object in advanced settings.');target=target[key];}target[path.at(-1)]=entry[0];}
 s.payload=JSON.stringify(payload,null,2);
}
export function prepareEnginePayload(s){const payload=readEnginePayload(s),operation=currentOperation(s.tool,payload);if(operation)selectOperation(s,operation.value||operation.entry[0]);return readEnginePayload(s);}
export function engineFields(s){
 let payload;try{payload=readEnginePayload(s);}catch{return '<div class="sw-error">Review the JSON in Advanced inputs before configuring this operation.</div>';}
 const operation=currentOperation(s.tool,payload),defaults=operation?.entry[2]||{},fields={...defaults,...payload};
 const rows=Object.entries(fields).filter(([key,value])=>key!==operation?.spec.key&&!['operation','kind'].includes(key)&&(typeof value==='number'||typeof value==='string'||typeof value==='boolean'||value===null&&numericNulls.has(key)));
 return `${operation?`<label class="sq-operation">Operation<select id="sq-operation">${operation.spec.items.map(entry=>`<option value="${esc(entry[0])}" ${entry===operation.entry?'selected':''}>${esc(entry[1])}</option>`).join('')}</select></label>`:''}<div class="sq-parameter-grid">${rows.map(([key,value])=>{
 const label=esc(parameterLabel(key));
 if(typeof value==='boolean')return `<label class="sw-check"><input type="checkbox" data-sq-parameter="${esc(key)}" data-value-type="boolean" ${value?'checked':''}>${label}</label>`;
 if(choices[key])return `<label>${label}<select data-sq-parameter="${esc(key)}" data-value-type="string">${[...new Set([value,...choices[key]])].filter(v=>v!==null).map(v=>`<option ${value===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
 const number=typeof value==='number'||value===null&&numericNulls.has(key);
 return `<label>${label}<input data-sq-parameter="${esc(key)}" data-value-type="${number?'number':'string'}" ${number?'type="number" step="any"':''} value="${esc(value??'')}" ${value===null?'placeholder="Required from your data"':''}></label>`;
 }).join('')||'<p class="sw-help">Add the reviewed geometry, observations or model arrays in Advanced inputs below.</p>'}</div>`;
}
export function resultSummary(value){
 if(!value)return `<div class="sw-inspector-empty">${seismicIcon('spectrum')}<h3>Your result appears here</h3><p>Configure the operation, review its estimate and run it. Results remain proposals until reviewed.</p></div>`;
 const rows=[];
 function visit(item,path,depth){if(rows.length>=12||depth>4||item===null)return;if(item&&typeof item==='object'&&!Array.isArray(item)){if(Array.isArray(item.shape)){rows.push([path,item.shape.join(' × ')]);return;}for(const [key,part]of Object.entries(item))if(!['values','samples','wavelet','configuration','graphSnapshot','history'].includes(key))visit(part,path?path+'.'+key:key,depth+1);}else if(['string','number','boolean'].includes(typeof item))rows.push([path,String(item)]);}
 visit(value,'',0);
 return `<dl class="sw-meta">${rows.map(([key,item])=>`<dt>${esc(key)}</dt><dd>${esc(item)}</dd>`).join('')}</dl><details class="sw-inspector-section"><summary>Full result details</summary><pre class="sq-result">${esc(JSON.stringify(value,null,2))}</pre></details>`;
}
